@test
def test_polynomial():
    X = data(30, 3)
    assert close(PolynomialFeatures(2).fit_transform(X), poly2)
    assert close(PolynomialFeatures((2, 3), interaction_only=True, include_bias=False).fit_transform(X), poly_int)
    assert PolynomialFeatures(2).fit(X).get_feature_names_out() == poly_names
test_polynomial()

@test
def test_spline():
    X = data(30, 3)
    assert close(SplineTransformer(n_knots=4, degree=3).fit_transform(X), spl)
    assert close(SplineTransformer(n_knots=3, degree=2, knots="quantile", extrapolation="linear").fit(X).transform(X * 1.5), spl_q)
    assert close(SplineTransformer(n_knots=4, degree=3, extrapolation="periodic").fit_transform(X), spl_per)
test_spline()

@test
def test_quantile():
    X = data(30, 3)
    qt = QuantileTransformer(n_quantiles=10).fit(X)
    assert close(qt.transform(X), qt_u)
    assert close(qt.inverse_transform(qt.transform(X)), qt_inv)
    assert close(QuantileTransformer(n_quantiles=15, output_distribution="normal").fit_transform(X), qt_n)
    assert close(quantile_transform(X, n_quantiles=12), qt_fn)
test_quantile()

@test
def test_kbins():
    X = data(30, 3)
    k = KBinsDiscretizer(n_bins=4, encode="ordinal", strategy="uniform").fit(X)
    assert close(k.transform(X), kb_uniform) and close(cat(k.bin_edges_), kb_uniform_edges)
    k2 = KBinsDiscretizer(n_bins=4, encode="ordinal", strategy="quantile").fit(X)
    assert close(k2.transform(X), kb_quantile) and close(cat(k2.bin_edges_), kb_quantile_edges)
    k3 = KBinsDiscretizer(n_bins=4, encode="ordinal", strategy="kmeans").fit(X)
    assert close(k3.transform(X), kb_kmeans) and close(cat(k3.bin_edges_), kb_kmeans_edges, 1e-6, 1e-8)
    assert close(KBinsDiscretizer(n_bins=3, encode="onehot-dense").fit_transform(X), kb_oh)
test_kbins()

@test
def test_power():
    X = data(30, 3)
    pt = PowerTransformer().fit(X)
    assert close(pt.lambdas_, pt_yj_l, 1e-6, 1e-8)
    assert close(pt.transform(X), pt_yj, 1e-6, 1e-8)
    assert close(pt.inverse_transform(pt.transform(X)), pt_yj_inv, 1e-6, 1e-8)
    Xp = np.abs(X) + 0.5
    pb = PowerTransformer(method="box-cox").fit(Xp)
    assert close(pb.lambdas_, pt_bc_l, 1e-6, 1e-8)
    assert close(pb.transform(Xp), pt_bc, 1e-6, 1e-8)
    assert close(power_transform(X, standardize=False), pt_fn, 1e-6, 1e-8)
test_power()

@test
def test_target_encoder():
    Xc = np.zeros((40, 2)); yr = np.zeros(40)
    for i in range(40):
        Xc[i, 0] = float(i % 3); Xc[i, 1] = float((i * 7) % 4)
        yr[i] = ((i * 37) % 11) / 3.0 + (i % 3)
    te = TargetEncoder(random_state=0)
    assert close(te.fit_transform(Xc, yr), te_ft)
    assert close(te.transform(Xc), te_tr)
    assert close(cat(te.encodings_), te_enc)
    te2 = TargetEncoder(smooth=2.0, cv=3, shuffle=False)
    assert close(te2.fit_transform(Xc, yr), te2_ft)
test_target_encoder()
